{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much does a kitchen remodel cost in Kansas City?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most kitchens land between $25 K and $85 K. See the full breakdown in our Kitchen Cost Guide."
      }
    },
    {
      "@type": "Question",
      "name": "Do I need to move out during the remodel?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Not always. For phased projects we isolate work zones so you can stay. For gut-level jobs we outline temporary housing options."
      }
    },
    {
      "@type": "Question",
      "name": "How long will my project take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Typical timelines: Kitchens 6–10 weeks, Bathrooms 4–6 weeks, Decks 3–5 weeks. You receive a detailed schedule before work begins."
      }
    },
    {
      "@type": "Question",
      "name": "What permits are required in Johnson County and KC Metro?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We pull all building, electrical, and mechanical permits on your behalf and coordinate inspections with each municipality."
      }
    },
    {
      "@type": "Question",
      "name": "Can I supply my own materials?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, but homeowner-supplied items can delay timelines. We review specs first to keep warranties intact."
      }
    },
    {
      "@type": "Question",
      "name": "How do you handle change orders and surprise costs?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Nothing proceeds without your written approval. Every change order lists scope, price, and days added—no surprises."
      }
    },
    {
      "@type": "Question",
      "name": "What payment schedule do you use?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "50 % deposit to secure materials and scheduling, 40 % mid-project after rough-in inspections, and the final 10 % at the walkthrough once all punch-list items are complete."
      }
    },
    {
      "@type": "Question",
      "name": "How soon can you start?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Start windows are typically 4–8 weeks after contract signing to allow for design, permits, and ordering."
      }
    },
    {
      "@type": "Question",
      "name": "What’s the first step?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Book a free walkthrough. We’ll discuss scope, budget, and timelines, then send a transparent proposal."
      }
    }
  ]
}

